#!/bin/bash
# atest.sh <gcc prefix> : the exact compile command glibc's `make check` uses for math/atest-exp.c, with a chosen gcc 4.6.4
JT=~/dev/stdio-noob; G216=$JT/g216; . $G216/env.sh; P=$1
cd $G216/gf/glibc-2.16.0/math
$P/bin/gcc  -I ~/dev/stdio-noob/g216/gf/glibc-2.16.0/nptl/sysdeps/pthread/bits -D BOOTSTRAP_GLIBC=1 -L ~/dev/stdio-noob/g216/gf/glibc-2.16.0 -L ~/dev/stdio-noob/gl/out/lib atest-exp.c -c -std=gnu99 -fgnu89-inline  -O2 -Wall -Winline -Wwrite-strings -fmerge-all-constants -frounding-math -g -Wstrict-prototypes -mpreferred-stack-boundary=4  -Wa,-mtune=i686    -Wno-uninitialized   -D__NO_MATH_INLINES -D__LIBC_INTERNAL_MATH_INLINES -I../include -I~/dev/stdio-noob/g216/gf/glibc-2.16.0/build/math -I~/dev/stdio-noob/g216/gf/glibc-2.16.0/build -I../nptl/sysdeps/unix/sysv/linux/i386/i686 -I../sysdeps/unix/sysv/linux/i386/i686 -I../nptl/sysdeps/unix/sysv/linux/i386 -I../nptl/sysdeps/unix/sysv/linux/x86 -I../sysdeps/unix/sysv/linux/x86 -I../sysdeps/unix/sysv/linux/i386/nptl -I../sysdeps/unix/sysv/linux/i386 -I../nptl/sysdeps/unix/sysv/linux -I../nptl/sysdeps/pthread -I../sysdeps/pthread -I../sysdeps/unix/sysv/linux -I../sysdeps/gnu -I../sysdeps/unix/inet -I../nptl/sysdeps/unix/sysv -I../sysdeps/unix/sysv -I../sysdeps/unix/i386 -I../nptl/sysdeps/unix -I../sysdeps/unix -I../sysdeps/posix -I../sysdeps/i386/i686/fpu/multiarch -I../sysdeps/i386/i686/fpu -I../sysdeps/i386/i686/multiarch -I../nptl/sysdeps/i386/i686 -I../sysdeps/i386/i686 -I../sysdeps/i386/i486 -I../nptl/sysdeps/i386/i486 -I../sysdeps/i386/fpu -I../sysdeps/x86/fpu -I../nptl/sysdeps/i386 -I../sysdeps/i386 -I../sysdeps/x86 -I../sysdeps/wordsize-32 -I../sysdeps/ieee754/ldbl-96 -I../sysdeps/ieee754/dbl-64 -I../sysdeps/ieee754/flt-32 -I../sysdeps/ieee754 -I../sysdeps/generic -I../nptl  -I.. -I../libio -I. -nostdinc -isystem ~/dev/stdio-noob/g46/mb2/out/bin/../lib/gcc/i686-unknown-linux-gnu/4.6.4/include -isystem ~/dev/stdio-noob/g46/mb2/out/bin/../lib/gcc/i686-unknown-linux-gnu/4.6.4/include-fixed -isystem ~/dev/stdio-noob/g216/hdr_out/include -D_LIBC_REENTRANT -include ../include/libc-symbols.h   -DNOT_IN_libc=1    -o ~/dev/stdio-noob/g216/gf/glibc-2.16.0/build/math/atest-exp.o -MD -MP -MF ~/dev/stdio-noob/g216/gf/glibc-2.16.0/build/math/atest-exp.o.dt -MT ~/dev/stdio-noob/g216/gf/glibc-2.16.0/build/math/atest-exp.o > /tmp/atest_$$.log 2>&1; rc=$?
grep -v warning /tmp/atest_$$.log | head -4 | cut -c1-160; echo "rc=$rc ICE=$(grep -c 'internal compiler error' /tmp/atest_$$.log) MPFR-assert=$(grep -c 'MPFR assertion' /tmp/atest_$$.log)"; rm -f /tmp/atest_$$.*
